"""Private WoWS Toolbox runtime path bootstrap."""

from pathlib import Path
import sys


PACKAGE_ROOT = Path(sys.executable).resolve().parents[2]
RUNTIME_IMPORT_DIRS = (
    "Backend",
    "BlenderExtractor/geometry_decoder",
    "BlenderExtractor/blender_extractor",
    "BlenderExtractor/blender_extractor/legends_assets",
    "FullAssembly/Ticonderoga1990/Mapping",
    "FullAssembly/Ticonderoga1990/ModelUberParser",
    "FullAssembly/Ticonderoga1990/PBRConverter",
    "FullAssembly/Ticonderoga1990/Pipeline",
    "FullAssembly/Ticonderoga1990/BlenderSceneAssembler",
    "FullAssembly/SelectedShip/PBRConverter",
    "FullAssembly/SelectedShip/Pipeline",
    "FullAssembly/SelectedShip/BlenderSceneAssembler",
)
for relative in reversed(RUNTIME_IMPORT_DIRS):
    candidate = PACKAGE_ROOT / relative
    if candidate.is_dir():
        sys.path.insert(0, str(candidate))